contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint ticketValue) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (ticketValue)); require(ticketValue <= 1000000000000000000000000000000);
        require(ticketValue == 10);
        require(address(this).balance >= ticketValue);

        uint bankBefore = c.bank().balance;
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint contractBalanceBefore = address(c).balance;

        c.play{value: ticketValue}(); if (__ESBMC_reverted()) return;

        uint bankAfter = c.bank().balance;
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint contractBalanceAfter = address(c).balance;

        assert(
            (contractBalanceAfter == contractBalanceBefore + ticketValue) ||
            (contractBalanceAfter == contractBalanceBefore + ticketValue - ticketValue)
        );
    }

    receive() external payable {}
}

