// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 ticketValue) internal {
        ticketValue = bound(ticketValue, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        ticketValue = 10;
        vm.assume(address(this).balance >= ticketValue);
        uint bankBefore = c.bank().balance;
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        uint contractBalanceBefore = address(c).balance;
        try c.play{value: ticketValue}() {} catch { return; }
        uint bankAfter = c.bank().balance;
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        uint contractBalanceAfter = address(c).balance;
        assertTrue((contractBalanceAfter == contractBalanceBefore + ticketValue) ||
            (contractBalanceAfter == contractBalanceBefore + ticketValue - ticketValue));
    }

    function testFuzz_run(uint256 ticketValue) public {
        _run(ticketValue);
    }

    receive() external payable {}
}
